import re
import urllib.parse
import requests
import json

def task_func(myString, API_KEY):
    """
    Extracts URLs from a string, resolves domains to IPs, 
    and fetches geolocation data using the IP-API.
    """
    # Regex to find URLs
    url_pattern = r'https?://(?:[-\w.]|(?:%[\da-fA-F]{2}))+'
    urls = re.findall(url_pattern, myString)

    results = {}

    # Process each unique domain found
    unique_domains = set()
    for url in urls:
        domain = urllib.parse.urlparse(url).netloc
        # Remove port if present
        domain = domain.split(':')[0]
        unique_domains.add(domain)

    for domain in unique_domains:
        try:
            # Note: ip-api.com allows domain lookups directly
            # API endpoint: http://ip-api.com/json/{query}
            url = f"http://ip-api.com/json/{domain}"

            # If an API_KEY is required for a specific service (e.g., ip-api Pro),
            # it would be appended as a parameter.
            params = {'key': API_KEY} if API_KEY else {}

            response = requests.get(url, params=params, timeout=5)

            if response.status_code == 200:
                data = response.json()
                if data.get('status') == 'success':
                    results[domain] = data
                else:
                    results[domain] = None
            else:
                results[domain] = None
        except Exception:
            results[domain] = None

    return results

